export function smooth(a: number[], w: number): number[] {
  if (w <= 1 || a.length === 0) return a.slice()
  const out = new Array<number>(a.length)
  const half = Math.floor(w / 2)
  let sum = 0
  let lo = 0
  let hi = -1
  for (let i = 0; i < a.length; i++) {
    const wantLo = Math.max(0, i - half)
    const wantHi = Math.min(a.length - 1, i + half)
    while (hi < wantHi) sum += a[++hi]
    while (lo < wantLo) sum -= a[lo++]
    out[i] = sum / (hi - lo + 1)
  }
  return out
}

export interface Peak {
  index: number
  value: number
  prominence: number
}

export function findPeaks(a: number[], minProminence: number): Peak[] {
  const peaks: Peak[] = []
  const n = a.length
  for (let i = 1; i < n - 1; i++) {
    if (!(a[i] > a[i - 1] && a[i] >= a[i + 1])) continue
    let j = i
    while (j < n - 1 && a[j + 1] === a[i]) j++
    if (j < n - 1 && a[j + 1] > a[i]) continue
    let leftMin = a[i]
    let k = i - 1
    while (k >= 0 && a[k] <= a[i]) {
      if (a[k] < leftMin) leftMin = a[k]
      k--
    }
    let rightMin = a[i]
    k = j + 1
    while (k < n && a[k] <= a[i]) {
      if (a[k] < rightMin) rightMin = a[k]
      k++
    }
    const prom = a[i] - Math.max(leftMin, rightMin)
    if (prom >= minProminence) peaks.push({ index: i, value: a[i], prominence: prom })
  }
  return peaks
}

export function correlationLag(a: number[], b: number[], maxLag: number): { lag: number; corr: number } {
  const n = Math.min(a.length, b.length)
  if (n < 8) return { lag: 0, corr: 0 }
  const ma = a.reduce((x, y) => x + y, 0) / n
  const mb = b.reduce((x, y) => x + y, 0) / n
  let best = { lag: 0, corr: -Infinity }
  for (let lag = -maxLag; lag <= maxLag; lag++) {
    let num = 0
    let da = 0
    let db = 0
    for (let i = 0; i < n; i++) {
      const j = i + lag
      if (j < 0 || j >= n) continue
      const x = a[i] - ma
      const y = b[j] - mb
      num += x * y
      da += x * x
      db += y * y
    }
    const c = da > 0 && db > 0 ? num / Math.sqrt(da * db) : 0
    if (c > best.corr) best = { lag, corr: c }
  }
  return best
}

import { World, C } from '../src/sim/world'
import { DEFAULT_PARAMS, PRESETS, presetParams, type Params } from '../src/sim/params'

interface Opts {
  preset: string
  seconds: number
  every: number
  seeds: number[]
  overrides: Partial<Params>
  quiet: boolean
}

function parseArgs(): Opts {
  const o: Opts = { preset: 'balanced', seconds: 1200, every: 20, seeds: [], overrides: {}, quiet: false }
  for (const a of process.argv.slice(2)) {
    const [k, v] = a.replace(/^--/, '').split('=')
    if (k === 'preset') o.preset = v
    else if (k === 'seconds') o.seconds = Number(v)
    else if (k === 'every') o.every = Number(v)
    else if (k === 'seeds') o.seeds = v.split(',').map(Number)
    else if (k === 'quiet') o.quiet = true
    else if (k.startsWith('C.')) (C as Record<string, number>)[k.slice(2)] = Number(v)
    else if (k in DEFAULT_PARAMS) (o.overrides as Record<string, number>)[k] = Number(v)
  }
  return o
}

function peaks(series: number[], minProm: number): number {
  let count = 0
  let last = series[0]
  let dir = 0
  let ref = series[0]
  for (const v of series) {
    if (dir >= 0 && v > last) dir = 1
    if (dir === 1 && v < last - minProm && last - ref >= minProm * 0.5) {
      count++
      dir = -1
      ref = last
    }
    if (dir === -1 && v > last + minProm) {
      dir = 1
      ref = last
    }
    if (v > last && dir === 1) last = v
    else if (dir !== 1) last = v
    if (dir === 1 && v >= last) last = v
  }
  return count
}

function run(preset: string, seed: number | undefined, o: Opts) {
  const params: Params = { ...presetParams(preset), ...o.overrides }
  if (seed !== undefined) params.seed = seed
  const w = new World(params)
  w.emit = false
  const ticks = Math.round(o.seconds / C.DT)
  const t0 = Date.now()
  if (!o.quiet) console.log(`\n== ${preset} seed=${params.seed}`)
  let nextPrint = 0
  for (let i = 0; i < ticks; i++) {
    w.step()
    if (!o.quiet && w.t >= nextPrint) {
      const s = w.history[w.history.length - 1]
      console.log(
        `t=${w.t.toFixed(0).padStart(5)} fruit=${String(w.fruitCount).padStart(4)} blue=${String(w.blueCount).padStart(4)} red=${String(w.redCount).padStart(3)}  bE=${s.blueEnergy.toFixed(0)} rE=${s.redEnergy.toFixed(0)} bspd=${s.blueSpeed.toFixed(2)} bvis=${s.blueVision.toFixed(1)} rspd=${s.redSpeed.toFixed(2)}`,
      )
      nextPrint += o.every
    }
    if (w.blueCount === 0 && w.redCount === 0) break
  }
  const h = w.history
  const half = h.slice(Math.floor(h.length / 2))
  const bl = half.map((s) => s.blue)
  const rd = half.map((s) => s.red)
  const stat = (a: number[]) => `${Math.min(...a)}-${Math.max(...a)} (mean ${(a.reduce((x, y) => x + y, 0) / a.length).toFixed(0)})`
  const bp = peaks(h.map((s) => s.blue), 8)
  const rp = peaks(h.map((s) => s.red), 3)
  console.log(
    `${preset} seed=${params.seed}: end t=${w.t.toFixed(0)} blue=${w.blueCount} red=${w.redCount} | 2nd-half blue ${stat(bl)} red ${stat(rd)} | blue peaks=${bp} red peaks=${rp} | born b/r=${w.stats.blueBorn}/${w.stats.redBorn} drained=${w.stats.blueDrained} contacts=${w.stats.contacts} fruitEaten=${w.stats.fruitEaten} | ${((Date.now() - t0) / 1000).toFixed(1)}s`,
  )
}

const o = parseArgs()
if (o.preset === 'all') {
  for (const p of PRESETS) run(p.id, undefined, { ...o, quiet: true })
} else if (o.seeds.length) {
  for (const s of o.seeds) run(o.preset, s, { ...o, quiet: o.quiet })
} else {
  run(o.preset, undefined, o)
}

import { World, C } from '../src/sim/world'
import { presetParams, type Params } from '../src/sim/params'
import { smooth, findPeaks } from '../src/sim/signal'

type Space = Partial<Record<keyof Params, [number, number]>>

interface Args {
  n: number
  seconds: number
  seeds: number[]
  base: string
  space: Space
  consts: Record<string, [number, number]>
  seedRng: number
}

const presetOverrides: Partial<Params> = {}

const args: Args = {
  n: 60,
  seconds: 1500,
  seeds: [1, 2, 3],
  base: 'balanced',
  seedRng: 1,
  space: {
    redStrength: [8, 30],
    redPause: [2, 8],
    redUse: [0.8, 2.2],
    redVision: [5, 10],
    redSpeed: [2.4, 3.2],
    redCopy: [70, 95],
  },
  consts: {},
}

for (const a of process.argv.slice(2)) {
  const [k, v] = a.replace(/^--/, '').split('=')
  if (k === 'n') args.n = Number(v)
  else if (k === 'seconds') args.seconds = Number(v)
  else if (k === 'base') args.base = v
  else if (k === 'seedRng') args.seedRng = Number(v)
  else if (k === 'seeds') args.seeds = v.split(',').map(Number)
  else if (k === 'space') {
    args.space = {}
    for (const part of v.split(';')) {
      const [name, lo, hi] = part.split(':')
      ;(args.space as Record<string, [number, number]>)[name] = [Number(lo), Number(hi)]
    }
  } else if (k === 'consts') {
    for (const part of v.split(';')) {
      const [name, lo, hi] = part.split(':')
      args.consts[name] = [Number(lo), Number(hi)]
    }
  } else if (k.startsWith('P.')) {
    ;(presetOverrides as Record<string, number>)[k.slice(2)] = Number(v)
  }
}

function lcg(seed: number) {
  let s = seed >>> 0
  return () => {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0
    return s / 4294967296
  }
}
const rnd = lcg(args.seedRng)
const constDefaults = { ...C } as Record<string, number>

interface Result {
  score: number
  survived: number
  amp: number
  peaks: number
  detail: string
  cfg: string
}

function evaluate(over: Partial<Params>, consts: Record<string, number>): Result {
  let survived = 0
  let ampSum = 0
  let peakSum = 0
  const details: string[] = []
  for (const [k, v] of Object.entries(consts)) (C as Record<string, number>)[k] = v
  for (const seed of args.seeds) {
    const params: Params = { ...presetParams(args.base), ...presetOverrides, ...over, seed }
    const w = new World(params)
    w.emit = false
    const ticks = Math.round(args.seconds / C.DT)
    for (let i = 0; i < ticks; i++) {
      w.step()
      if (w.blueCount === 0 || w.redCount === 0) break
    }
    const alive = w.blueCount > 0 && w.redCount > 0 && w.t >= args.seconds - 1
    if (alive) survived++
    const h = w.history.slice(Math.floor(w.history.length * 0.25))
    const bl = smooth(h.map((s) => s.blue), 9)
    const rd = smooth(h.map((s) => s.red), 9)
    const mb = bl.reduce((a, b) => a + b, 0) / Math.max(1, bl.length)
    const mr = rd.reduce((a, b) => a + b, 0) / Math.max(1, rd.length)
    const pb = findPeaks(bl, Math.max(6, mb * 0.3)).length
    const pr = findPeaks(rd, Math.max(2, mr * 0.3)).length
    const amp = mb > 0 ? (Math.max(...bl) - Math.min(...bl)) / mb : 0
    ampSum += amp
    peakSum += Math.min(pb, pr)
    details.push(`${alive ? 'ok' : 'X' + w.t.toFixed(0)}:b${mb.toFixed(0)}/r${mr.toFixed(0)}/p${pb},${pr}`)
  }
  for (const [k, v] of Object.entries(constDefaults)) (C as Record<string, number>)[k] = v
  const n = args.seeds.length
  const amp = ampSum / n
  const peaks = peakSum / n
  const score = survived / n * 10 + Math.min(peaks, 6) + Math.min(amp, 1.2)
  return { score, survived, amp, peaks, detail: details.join(' '), cfg: '' }
}

const results: Result[] = []
for (let i = 0; i < args.n; i++) {
  const over: Partial<Params> = {}
  for (const [k, [lo, hi]] of Object.entries(args.space)) {
    ;(over as Record<string, number>)[k] = +(lo + (hi - lo) * rnd()).toFixed(2)
  }
