          <path d={areaPath(fruitPts, baseY)} fill="url(#gFruit)" />
          <path d={linePath(fruitPts)} fill="none" stroke={COLORS.fruit} strokeWidth={2} strokeLinejoin="round" strokeLinecap="round" strokeDasharray="1 0" opacity={0.9} />
