+  --shadow: 0 1px 0 rgba(255, 255, 255, 0.9) inset, 0 8px 24px -10px rgba(96, 74, 32, 0.28), 0 2px 5px rgba(96, 74, 32, 0.08);
+  --radius: 22px;
+  --font-display: 'Fredoka Variable', 'Fredoka', ui-rounded, system-ui, sans-serif;
+  --font-body: 'Nunito Variable', 'Nunito', ui-rounded, system-ui, sans-serif;
+  color-scheme: light;
+}
+
+* {
+  box-sizing: border-box;
+}
+
+html,
+body,
+#root {
+  height: 100%;
+  margin: 0;
+}
+
+body {
+  font-family: var(--font-body);
+  font-size: 14px;
+  line-height: 1.4;
+  color: var(--ink);
+  background:
+    radial-gradient(1200px 700px at 8% -10%, #dff0ff 0%, transparent 60%),
+    radial-gradient(1000px 700px at 100% 110%, #e2f5d4 0%, transparent 60%),
+    var(--bg);
+  -webkit-font-smoothing: antialiased;
+}
+
+h1,
+h2,
+h3,
+button,
+.pill,
+.badge {
+  font-family: var(--font-display);
+}
+
+button {
+  cursor: pointer;
+  color: inherit;
+}
+
+button:focus-visible,
+input:focus-visible,
+a:focus-visible {
+  outline: 3px solid rgba(139, 92, 246, 0.55);
+  outline-offset: 2px;
+}
+
+.app {
+  display: grid;
+  height: 100%;
+  min-height: 0;
+  grid-template-columns: 318px minmax(0, 1fr) 356px;
+  grid-template-rows: auto minmax(0, 1fr);
+  grid-template-areas:
+    'head head head'
+    'left main right';
+  gap: 14px;
+  padding: 12px 14px 14px;
+}
+
+.topbar {
+  grid-area: head;
+  display: flex;
+  align-items: center;
+  gap: 18px;
+  flex-wrap: wrap;
+  min-height: 52px;
+}
+
+.brand {
+  display: flex;
+  align-items: center;
+  gap: 12px;
+  min-width: 250px;
+}
+
+.brand h1 {
+  margin: 0;
+  font-size: 27px;
+  font-weight: 600;
+  letter-spacing: 0.1px;
+  line-height: 1;
+  color: var(--ink);
+}
+
+.logo {
+  position: relative;
+  width: 44px;
+  height: 40px;
+  flex: none;
+}
+
+.logo i {
+  position: absolute;
+  display: block;
+  border-radius: 50% 50% 46% 46%;
+  box-shadow: inset 0 -5px 0 rgba(0, 0, 0, 0.12), inset 0 4px 0 rgba(255, 255, 255, 0.35);
+}
+
+.logo .b {
+  left: 0;
+  top: 4px;
+  width: 26px;
+  height: 32px;
+  background: var(--blue);
+  transform: rotate(-8deg);
+  animation: bob 2.8s ease-in-out infinite;
+}
+
+.logo .r {
+  right: 0;
+  top: 9px;
+  width: 22px;
+  height: 27px;
+  background: var(--red);
+  transform: rotate(9deg);
+  animation: bob 2.8s ease-in-out infinite 0.5s;
+}
+
+@keyframes bob {
+  0%,
+  100% {
+    translate: 0 0;
+  }
+  50% {
+    translate: 0 -3px;
+  }
+}
+
+/* ---------- toolbar ---------- */
+
+.toolbar {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  flex-wrap: wrap;
+}
+
+.btn {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  height: 40px;
+  padding: 0 16px;
+  font-size: 15px;
+  font-weight: 500;
+  border: 2px solid var(--line);
+  border-radius: 999px;
+  background: var(--card);
+  box-shadow: 0 3px 0 var(--line);
+  transition:
+    transform 0.12s,
+    box-shadow 0.12s,
+    background 0.15s;
+}
+
+.btn:hover {
+  background: #fff;
+  transform: translateY(-1px);
+  box-shadow: 0 4px 0 var(--line);
+}
+
+.btn:active {
+  transform: translateY(2px);
+  box-shadow: 0 1px 0 var(--line);
+}
+
+.btn .ico {
+  font-size: 14px;
+  line-height: 1;
+}
+
+.btn.primary {
+  min-width: 108px;
+  justify-content: center;
+  color: #fff;
+  background: var(--green);
+  border-color: #3c9a3f;
+  box-shadow: 0 3px 0 #2f7d32;
+}
+
+.btn.primary:hover {
+  background: #57b95a;
+}
+
+.btn.primary.playing {
+  background: #ff9f43;
+  border-color: #eb8a2c;
+  box-shadow: 0 3px 0 #c9711c;
+}
+
+.speed {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  height: 40px;
+  padding: 0 14px;
+  border-radius: 999px;
+  background: var(--card);
+  border: 2px solid var(--line);
+  font-family: var(--font-display);
+}
+
+.speed label {
+  color: var(--muted);
+  font-size: 13px;
+}
+
+.speed output {
+  min-width: 34px;
+  font-weight: 600;
+  text-align: right;
+}
+
+.speed input {
+  width: 120px;
+}
+
+/* ---------- columns ---------- */
+
+.col-left,
+.col-right {
+  min-height: 0;
+  overflow-y: auto;
+  overflow-x: hidden;
+  padding: 2px 6px 6px 2px;
+  scrollbar-width: thin;
+  scrollbar-color: #d8c9a6 transparent;
+}
+
+.col-left {
+  grid-area: left;
+}
+
+.col-right {
+  grid-area: right;
+  display: flex;
+  flex-direction: column;
+  gap: 14px;
+}
+
+.col-main {
+  grid-area: main;
+  min-height: 0;
+  min-width: 0;
+  display: flex;
+  flex-direction: column;
+  gap: 14px;
+}
+
+.panel {
+  position: relative;
+  background: var(--card);
+  border: 2px solid var(--line);
+  border-radius: var(--radius);
+  box-shadow: var(--shadow);
+  padding: 14px 16px 16px;
+}
+
+.panel-title {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  margin-bottom: 10px;
+}
+
+.panel-title h2 {
+  margin: 0;
+  margin-right: auto;
+  font-size: 18px;
+  font-weight: 600;
+  letter-spacing: 0.1px;
+}
+
+.hint {
+  color: var(--muted);
+  font-size: 12px;
+  font-family: var(--font-body);
+}
+
+.caption {
+  margin: 6px 0 0;
+  color: var(--muted);
+  font-size: 12px;
+}
+
+/* ---------- stage ---------- */
+
+.stage {
+  position: relative;
+  flex: 1 1 0;
+  min-height: 300px;
+  overflow: hidden;
+  border-radius: 28px;
+  border: 2px solid var(--line);
+  box-shadow: var(--shadow);
+  background:
+    radial-gradient(90% 70% at 50% 108%, #ffe9c4 0%, transparent 62%),
+    radial-gradient(70% 60% at 20% 0%, #fffbe9 0%, transparent 60%),
+    linear-gradient(180deg, #bfe4ff 0%, #dff2ff 42%, #f6efdb 100%);
+}
+
+.garden-canvas {
+  position: absolute;
+  inset: 0;
+}
+
+.hud {
+  position: absolute;
+  top: 12px;
+  left: 12px;
+  display: flex;
+  flex-wrap: wrap;
+  gap: 8px;
+  pointer-events: none;
+}
+
+.pill {
+  display: inline-flex;
+  align-items: center;
+  gap: 7px;
+  height: 32px;
+  padding: 0 13px;
+  border-radius: 999px;
+  background: rgba(255, 253, 248, 0.92);
+  border: 2px solid rgba(255, 255, 255, 0.9);
+  box-shadow: 0 3px 10px -4px rgba(70, 60, 40, 0.35);
+  font-size: 14px;
+  font-weight: 500;
+  color: var(--ink);
+}
+
+.pill b {
+  font-weight: 600;
+  font-variant-numeric: tabular-nums;
+}
+
+.pill i {
+  width: 12px;
+  height: 12px;
+  border-radius: 50%;
+  display: block;
+}
+
+.pill.fruit i {
+  background: #9be04a;
+  box-shadow: 0 0 0 2px #e4f5cf;
+}
+
+.pill.blue i {
+  background: var(--blue);
+  box-shadow: 0 0 0 2px var(--blue-soft);
+}
+
+.pill.red i {
+  background: var(--red);
+  box-shadow: 0 0 0 2px var(--red-soft);
+}
+
+.pill.time {
+  color: var(--muted);
+}
+
+.pill.time b {
+  color: var(--ink);
+}
+
+.stage-tools {
+  position: absolute;
+  top: 12px;
+  right: 12px;
+  display: flex;
+  gap: 8px;
+}
+
+.chip-btn {
+  height: 30px;
+  padding: 0 12px;
+  border-radius: 999px;
+  border: 2px solid rgba(255, 255, 255, 0.9);
+  background: rgba(255, 253, 248, 0.85);
+  font-size: 13px;
+  box-shadow: 0 3px 10px -4px rgba(70, 60, 40, 0.35);
+}
+
+.chip-btn.on {
+  background: var(--violet);
+  border-color: #7a4be6;
+  color: #fff;
+}
+
+.stage-hint {
+  position: absolute;
+  bottom: 10px;
+  left: 50%;
+  transform: translateX(-50%);
+  padding: 4px 12px;
+  border-radius: 999px;
+  background: rgba(255, 253, 248, 0.7);
+  color: var(--muted);
+  font-size: 12px;
+  white-space: nowrap;
+  pointer-events: none;
+}
+
+.big-play {
+  position: absolute;
+  left: 50%;
+  top: 50%;
+  transform: translate(-50%, -50%);
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+  height: 58px;
+  padding: 0 28px;
+  font-size: 22px;
+  font-weight: 600;
+  color: #fff;
+  background: var(--green);
+  border: 3px solid #fff;
+  border-radius: 999px;
+  box-shadow:
+    0 5px 0 #2f7d32,
+    0 14px 30px -8px rgba(40, 90, 40, 0.5);
+  animation: pulse 1.6s ease-in-out infinite;
+}
+
+@keyframes pulse {
+  50% {
+    transform: translate(-50%, -50%) scale(1.06);
+  }
+}
+
+/* ---------- controls ---------- */
+
+.controls .presets {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 8px;
+}
+
+.preset {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  min-height: 42px;
+  padding: 6px 10px;
+  text-align: left;
+  font-size: 13.5px;
+  font-weight: 500;
+  line-height: 1.1;
+  border: 2px solid var(--line);
+  border-radius: 16px;
+  background: var(--card-2);
+  transition:
+    transform 0.12s,
+    background 0.15s,
+    border-color 0.15s;
+}
+
+.preset:hover {
+  transform: translateY(-1px);
+  background: #fff;
+}
+
+.preset.active {
+  border-color: var(--green);
+  background: var(--green-soft);
+  box-shadow: 0 0 0 3px rgba(76, 174, 79, 0.18);
+}
+
+.preset-emoji {
+  font-size: 20px;
+}
+
+.preset-blurb {
+  margin: 8px 2px 12px;
+  color: var(--muted);
+  font-size: 12.5px;
+  min-height: 18px;
+}
+
+.group {
+  margin-top: 10px;
+  border: 2px solid var(--line);
+  border-radius: 18px;
+  background: var(--card-2);
+  overflow: hidden;
+}
+
+.group.tone-blue {
+  --tone: var(--blue);
+  --tone-soft: var(--blue-soft);
+}
+.group.tone-red {
+  --tone: var(--red);
+  --tone-soft: var(--red-soft);
+}
+.group.tone-green {
+  --tone: var(--green);
+  --tone-soft: var(--green-soft);
+}
+.group.tone-violet {
+  --tone: var(--violet);
+  --tone-soft: var(--violet-soft);
+}
+.group.tone-sand {
+  --tone: var(--sand);
+  --tone-soft: var(--sand-soft);
+}
+
+.group-head {
+  display: flex;
+  align-items: center;
+  gap: 9px;
+  width: 100%;
+  padding: 9px 12px;
+  border: 0;
+  background: var(--tone-soft);
+  font-size: 15px;
+  font-weight: 600;
+  text-align: left;
+}
+
+.group-emoji {
+  font-size: 18px;
+}
+
+.group-title {
+  margin-right: auto;
+}
+
+.badge {
+  padding: 2px 8px;
+  font-size: 11px;
+  font-weight: 500;
+  color: #8a5a12;
+  background: #fff;
+  border-radius: 999px;
+  border: 1.5px solid var(--sand);
+}
+
+.chev {
+  width: 22px;
+  height: 22px;
+  display: grid;
+  place-items: center;
+  border-radius: 50%;
+  background: #fff;
+  color: var(--tone);
+  font-size: 16px;
+  line-height: 1;
+}
+
+.group-body {
+  padding: 8px 12px 12px;
+  display: flex;
+  flex-direction: column;
+  gap: 9px;
+}
+
+.slider {
+  --tone: var(--green);
+}
+.slider.tone-blue {
+  --tone: var(--blue);
+}
+.slider.tone-red {
+  --tone: var(--red);
+}
+.slider.tone-violet {
+  --tone: var(--violet);
+}
+.slider.tone-sand {
+  --tone: var(--sand);
+}
+
+.slider-head {
+  display: flex;
+  justify-content: space-between;
+  align-items: baseline;
+  gap: 8px;
+  font-size: 13px;
+}
+
+.slider-head label {
+  font-weight: 700;
+  color: #4a4663;
+}
+
+.slider-head output {
+  font-family: var(--font-display);
+  font-size: 13px;
+  color: var(--ink);
+  font-variant-numeric: tabular-nums;
+  background: #fff;
+  border-radius: 999px;
+  padding: 0 8px;
+  border: 1.5px solid var(--line);
+}
+
+.slider.dirty output {
+  border-color: var(--sand);
+  background: var(--sand-soft);
+}
+
+input[type='range'] {
+  --pct: 50%;
+  -webkit-appearance: none;
+  appearance: none;
+  width: 100%;
+  height: 22px;
+  margin: 0;
+  background: transparent;
+  cursor: pointer;
+  --tone: var(--green);
+}
+
+.slider input[type='range'] {
+  --tone: inherit;
+}
+
+input[type='range']::-webkit-slider-runnable-track {
+  height: 10px;
+  border-radius: 999px;
+  background: linear-gradient(90deg, var(--tone, var(--green)) var(--pct), #e9dfc9 var(--pct));
+  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.12);
+}
+
+input[type='range']::-moz-range-track {
+  height: 10px;
+  border-radius: 999px;
+  background: #e9dfc9;
+}
+
+input[type='range']::-moz-range-progress {
+  height: 10px;
+  border-radius: 999px;
+  background: var(--tone, var(--green));
+}
+
+input[type='range']::-webkit-slider-thumb {
+  -webkit-appearance: none;
+  width: 22px;
+  height: 22px;
+  margin-top: -6px;
+  border-radius: 50%;
+  background: #fff;
+  border: 3px solid var(--tone, var(--green));
+  box-shadow: 0 2px 5px rgba(60, 50, 30, 0.3);
+  transition: transform 0.1s;
+}
+
+input[type='range']::-moz-range-thumb {
+  width: 16px;
+  height: 16px;
+  border-radius: 50%;
+  background: #fff;
+  border: 3px solid var(--tone, var(--green));
+  box-shadow: 0 2px 5px rgba(60, 50, 30, 0.3);
+}
+
+input[type='range']:hover::-webkit-slider-thumb {
+  transform: scale(1.12);
+}
+
+.seed-row {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+}
+
+.seed-row label {
+  font-weight: 700;
+  color: #4a4663;
+  font-size: 13px;
+  margin-right: auto;
+}
+
+.seed-row input {
+  width: 92px;
+  height: 32px;
+  padding: 0 10px;
+  font: 600 14px var(--font-display);
+  border: 2px solid var(--line);
+  border-radius: 12px;
+  background: #fff;
+  color: var(--ink);
+}
+
+.seed-row.dirty input {
+  border-color: var(--sand);
+  background: var(--sand-soft);
+}
+
+.mini {
+  width: 32px;
+  height: 32px;
+  display: grid;
+  place-items: center;
+  padding: 0;
+  border-radius: 50%;
+  border: 2px solid var(--line);
+  background: #fff;
+  font-size: 14px;
+}
+
+.mini:hover {
+  background: var(--card-2);
+}
+
+.restart {
+  height: 38px;
+  border-radius: 14px;
+  border: 2px dashed var(--sand);
+  background: transparent;
+  color: #8a5a12;
+  font-size: 14px;
+  font-weight: 500;
+}
+
+.restart.ready {
+  border-style: solid;
+  background: var(--sand);
+  color: #fff;
+  animation: pulse-soft 1.4s ease-in-out infinite;
+}
+
+@keyframes pulse-soft {
+  50% {
+    box-shadow: 0 0 0 5px rgba(214, 154, 74, 0.28);
+  }
+}
+
+/* ---------- charts ---------- */
+
+.timeline {
+  flex: none;
+  padding-bottom: 10px;
+}
+
+.timeline .panel-title {
+  flex-wrap: wrap;
+  margin-bottom: 4px;
+}
+
+.seg {
+  display: inline-flex;
+  padding: 3px;
+  border-radius: 999px;
+  background: var(--card-2);
+  border: 2px solid var(--line);
+}
+
+.seg button {
+  height: 24px;
+  padding: 0 11px;
+  border: 0;
+  border-radius: 999px;
+  background: transparent;
+  font-size: 12.5px;
+  color: var(--muted);
+}
+
+.seg button.on {
+  background: var(--ink);
+  color: #fff;
+}
+
+.legend {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  gap: 6px 16px;
+  margin-bottom: 2px;
+  font-size: 13px;
+}
+
+.lg {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  font-family: var(--font-display);
+}
+
+.lg i {
+  width: 22px;
+  height: 6px;
+  border-radius: 999px;
+  display: block;
+}
+
+.lg.fruit i {
+  background: var(--green);
+}
+.lg.blue i {
+  background: var(--blue);
+}
+.lg.red i {
+  background: var(--red);
+}
+
+.lg b {
+  font-variant-numeric: tabular-nums;
+}
+
+.lg.note {
+  margin-left: auto;
+  color: var(--muted);
+  font-family: var(--font-body);
+  font-size: 12px;
+}
+
+.chart-box {
+  position: relative;
+  width: 100%;
+}
+
+.chart-box.center {
+  display: flex;
+  justify-content: center;
+}
+
+.chart-box svg {
+  display: block;
+  overflow: visible;
+}
+
+svg .grid {
+  stroke: #eee3cd;
+  stroke-width: 1;
+}
+
+svg .grid.v {
+  stroke-dasharray: 2 4;
+}
+
+svg .axis {
+  fill: var(--muted);
+  font: 500 11px var(--font-body);
+}
+
+svg .axis.fruit {
+  fill: var(--green);
+}
+svg .axis.label {
+  font: 600 11px var(--font-display);
+}
+svg .axis.label.blue {
+  fill: var(--blue);
+}
+svg .axis.label.red {
+  fill: var(--red);
+}
+
+svg .cursor {
+  stroke: #9a93b3;
+  stroke-width: 1.2;
+  stroke-dasharray: 3 3;
+}
+
+.tip {
+  position: absolute;
+  display: flex;
+  flex-direction: column;
+  gap: 1px;
+  padding: 6px 10px;
+  border-radius: 12px;
+  background: rgba(43, 41, 64, 0.92);
+  color: #fff;
+  font-size: 12px;
+  pointer-events: none;
+  min-width: 96px;
+}
+
+.tip strong {
+  font-family: var(--font-display);
+  font-size: 13px;
+}
+.tip .fruit {
+  color: #a5e59a;
+}
+.tip .blue {
+  color: #9cc7ff;
+}
+.tip .red {
+  color: #ffabb8;
+}
+
+.trait {
+  margin-top: 4px;
+}
+
+.trait-head {
+  display: flex;
+  gap: 10px;
+  align-items: baseline;
+  font-size: 12.5px;
+  font-variant-numeric: tabular-nums;
+}
+
+.trait-head b {
+  font-family: var(--font-display);
+  margin-right: auto;
+  font-size: 14px;
+}
+
+.trait-head .blue {
+  color: var(--blue);
+  font-weight: 700;
+}
+.trait-head .red {
+  color: var(--red);
+  font-weight: 700;
+}
+
+/* ---------- story ---------- */
+
+.story .headline {
+  margin: 0 0 8px;
+  padding: 10px 12px;
+  font: 500 17px/1.25 var(--font-display);
+  border-radius: 16px;
+  background: var(--green-soft);
+  color: #245d27;
+}
+
+.story.mood-waves .headline {
+  background: var(--violet-soft);
+  color: #4c2d9e;
+}
+.story.mood-small .headline {
+  background: var(--sand-soft);
+  color: #7a4f10;
+}
+.story.mood-blue-only .headline,
+.story.mood-red-fading .headline,
+.story.mood-empty .headline {
+  background: var(--red-soft);
+  color: #9b2236;
+}
+.story.mood-warming .headline {
+  background: var(--blue-soft);
+  color: #22508f;
+}
+
+.story-lines {
+  margin: 0;
+  padding-left: 18px;
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+  font-size: 13.5px;
+}
+
+.story-lines li::marker {
+  color: var(--green);
+}
+
+.chips {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 6px;
+  margin: 12px 0 0;
+}
+
+.chip {
+  padding: 6px 8px;
+  border-radius: 12px;
+  background: var(--card-2);
+  border: 1.5px solid var(--line);
+}
+
+.chip dt {
+  color: var(--muted);
+  font-size: 11px;
+}
+
+.chip dd {
+  margin: 0;
+  font: 600 16px var(--font-display);
+  font-variant-numeric: tabular-nums;
+}
+
+/* ---------- inspector ---------- */
+
+.inspector-empty {
+  display: flex;
+  align-items: center;
+  gap: 12px;
+  color: var(--muted);
+  font-size: 13.5px;
+}
+
+.inspector-empty p {
+  margin: 0;
+}
+
+.pointer {
+  font-size: 30px;
+  animation: bob 2s ease-in-out infinite;
+}
+
+.inspector.blue {
+  border-color: #b9d5ff;
+}
+.inspector.red {
+  border-color: #ffc2cc;
+}
+
+.who {
+  display: flex;
+  align-items: center;
+  gap: 12px;
+  margin-bottom: 12px;
+}
+
+.avatar {
+  width: 40px;
+  height: 46px;
+  border-radius: 50% 50% 46% 46%;
+  box-shadow:
+    inset 0 -6px 0 rgba(0, 0, 0, 0.14),
+    inset 0 5px 0 rgba(255, 255, 255, 0.4);
+  position: relative;
+}
+
+.avatar::before,
+.avatar::after {
+  content: '';
+  position: absolute;
+  top: 16px;
+  width: 7px;
+  height: 9px;
+  background: #fff;
+  border-radius: 50%;
+  box-shadow: inset 0 -3px 0 #1a1b3a;
+}
+
+.avatar::before {
+  left: 9px;
+}
+.avatar::after {
+  right: 9px;
+}
+
+.avatar.blue {
+  background: var(--blue);
+}
+.avatar.red {
+  background: var(--red);
+}
+
+.who .name {
+  font: 600 20px/1.1 var(--font-display);
+}
+
+.who .sub {
+  color: var(--muted);
+  font-size: 12.5px;
+}
+
+.energy-head {
+  display: flex;
+  justify-content: space-between;
+  font-size: 13px;
+  font-weight: 700;
+}
+
+.energy-head b {
+  font-family: var(--font-display);
+  font-variant-numeric: tabular-nums;
+}
+
+.bar {
+  position: relative;
+  height: 14px;
+  margin: 5px 0 3px;
+  border-radius: 999px;
+  background: #ebe1cb;
+  overflow: hidden;
+}
+
+.bar .fill {
+  height: 100%;
+  border-radius: 999px;
+  transition: width 0.15s;
+}
+
+.bar .fill.blue {
+  background: linear-gradient(90deg, #6cb0ff, var(--blue));
+}
+.bar .fill.red {
+  background: linear-gradient(90deg, #ff8fa0, var(--red));
+}
+
+.bar .mark {
+  position: absolute;
+  top: 0;
+  bottom: 0;
+  width: 3px;
+  background: rgba(43, 41, 64, 0.55);
+}
+
+.bar-note {
+  color: var(--muted);
+  font-size: 11.5px;
+}
+
+.rows {
+  margin: 12px 0 8px;
+  display: grid;
+  gap: 0;
+}
+
+.rows .row {
+  display: flex;
+  justify-content: space-between;
+  gap: 10px;
+  padding: 5px 0;
+  border-bottom: 1.5px dashed var(--line);
+  font-size: 13px;
+}
+
+.rows dt {
+  color: var(--muted);
+}
+
+.rows dd {
+  margin: 0;
+  font-weight: 700;
+  text-align: right;
+  font-variant-numeric: tabular-nums;
+}
+
+.rows dd.hot {
+  color: #d9541e;
+}
+
+.link {
+  padding: 0;
+  border: 0;
+  background: none;
+  color: var(--violet);
+  font: 700 13px var(--font-body);
+  text-decoration: underline dotted;
+}
+
+.check {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  font-size: 13px;
+  cursor: pointer;
+}
+
+.check input {
+  width: 17px;
+  height: 17px;
+  accent-color: var(--violet);
+}
+
+.rules-list {
+  margin: 0;
+  padding-left: 20px;
+  font-size: 13px;
+  display: flex;
+  flex-direction: column;
+  gap: 5px;
+}
+
+.rules-list .blue {
+  color: var(--blue);
+}
+.rules-list .red {
+  color: var(--red);
+}
+
+/* ---------- responsive ---------- */
+
+@media (max-width: 1240px) {
+  .app {
+    grid-template-columns: 290px minmax(0, 1fr) 320px;
+  }
+}
+
+@media (max-width: 1040px) {
+  html,
+  body,
+  #root {
+    height: auto;
+  }
+  .app {
+    height: auto;
+    grid-template-columns: minmax(0, 1fr);
+    grid-template-areas:
+      'head'
+      'main'
+      'right'
+      'left';
+  }
+  .col-left,
+  .col-right {
+    overflow: visible;
+  }
+  .stage {
+    flex: none;
+    height: min(74vh, 620px);
+  }
+  .brand h1 {
+    font-size: 23px;
+  }
+}
+
+@media (max-height: 760px) and (min-width: 1041px) {
+  .stage {
+    min-height: 240px;
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  * {
+    animation: none !important;
+    transition: none !important;
+  }
+}

success.afterFullFileContent:
:root {
  --bg: #f6efdf;
  --card: #fffdf8;
  --card-2: #fbf5e8;
  --ink: #2b2940;
  --muted: #7a7490;
  --line: #eadfc7;
  --blue: #3f8dff;
  --blue-soft: #e3efff;
  --red: #ff4863;
  --red-soft: #ffe6ea;
  --green: #4cae4f;
  --green-soft: #e4f5dc;
  --violet: #8b5cf6;
  --violet-soft: #efe8ff;
  --sand: #d69a4a;
  --sand-soft: #fbeed7;
  --shadow: 0 1px 0 rgba(255, 255, 255, 0.9) inset, 0 8px 24px -10px rgba(96, 74, 32, 0.28), 0 2px 5px rgba(96, 74, 32, 0.08);
  --radius: 22px;
  --font-display: 'Fredoka Variable', 'Fredoka', ui-rounded, system-ui, sans-serif;
  --font-body: 'Nunito Variable', 'Nunito', ui-rounded, system-ui, sans-serif;
  color-scheme: light;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.4;
  color: var(--ink);
  background:
    radial-gradient(1200px 700px at 8% -10%, #dff0ff 0%, transparent 60%),
    radial-gradient(1000px 700px at 100% 110%, #e2f5d4 0%, transparent 60%),
    var(--bg);
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3,
button,
.pill,
.badge {
  font-family: var(--font-display);
}

button {
  cursor: pointer;
  color: inherit;
}

button:focus-visible,
input:focus-visible,
a:focus-visible {
  outline: 3px solid rgba(139, 92, 246, 0.55);
  outline-offset: 2px;
}

.app {
  display: grid;
  height: 100%;
  min-height: 0;
  grid-template-columns: 318px minmax(0, 1fr) 356px;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas:
    'head head head'
    'left main right';
  gap: 14px;
  padding: 12px 14px 14px;
}

.topbar {
  grid-area: head;
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
  min-height: 52px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 250px;
}

.brand h1 {
  margin: 0;
  font-size: 27px;
  font-weight: 600;
  letter-spacing: 0.1px;
  line-height: 1;
  color: var(--ink);
}

.logo {
  position: relative;
  width: 44px;
  height: 40px;
  flex: none;
}

.logo i {
  position: absolute;
  display: block;
  border-radius: 50% 50% 46% 46%;
  box-shadow: inset 0 -5px 0 rgba(0, 0, 0, 0.12), inset 0 4px 0 rgba(255, 255, 255, 0.35);
}

.logo .b {
  left: 0;
  top: 4px;
  width: 26px;
  height: 32px;
  background: var(--blue);
  transform: rotate(-8deg);
  animation: bob 2.8s ease-in-out infinite;
}

.logo .r {
  right: 0;
  top: 9px;
  width: 22px;
  height: 27px;
  background: var(--red);
  transform: rotate(9deg);
  animation: bob 2.8s ease-in-out infinite 0.5s;
}

@keyframes bob {
  0%,
  100% {
    translate: 0 0;
  }
  50% {
    translate: 0 -3px;
  }
}

/* ---------- toolbar ---------- */

.toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 40px;
  padding: 0 16px;
  font-size: 15px;
  font-weight: 500;
  border: 2px solid var(--line);
  border-radius: 999px;
  background: var(--card);
  box-shadow: 0 3px 0 var(--line);
  transition:
    transform 0.12s,
    box-shadow 0.12s,
    background 0.15s;
}

.btn:hover {
  background: #fff;
  transform: translateY(-1px);
  box-shadow: 0 4px 0 var(--line);
}

.btn:active {
  transform: translateY(2px);
  box-shadow: 0 1px 0 var(--line);
}

.btn .ico {
  font-size: 14px;
  line-height: 1;
}

.btn.primary {
  min-width: 108px;
  justify-content: center;
  color: #fff;
  background: var(--green);
  border-color: #3c9a3f;
  box-shadow: 0 3px 0 #2f7d32;
}

.btn.primary:hover {
  background: #57b95a;
}

.btn.primary.playing {
  background: #ff9f43;
  border-color: #eb8a2c;
  box-shadow: 0 3px 0 #c9711c;
}

.speed {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 40px;
  padding: 0 14px;
  border-radius: 999px;
  background: var(--card);
  border: 2px solid var(--line);
  font-family: var(--font-display);
}

.speed label {
  color: var(--muted);
  font-size: 13px;
}

.speed output {
  min-width: 34px;
  font-weight: 600;
  text-align: right;
}

.speed input {
  width: 120px;
}

/* ---------- columns ---------- */

.col-left,
.col-right {
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 2px 6px 6px 2px;
  scrollbar-width: thin;
  scrollbar-color: #d8c9a6 transparent;
}

.col-left {
  grid-area: left;
}

.col-right {
  grid-area: right;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.col-main {
  grid-area: main;
  min-height: 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.panel {
  position: relative;
  background: var(--card);
  border: 2px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 14px 16px 16px;
}

.panel-title {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.panel-title h2 {
  margin: 0;
  margin-right: auto;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 0.1px;
}

.hint {
  color: var(--muted);
  font-size: 12px;
  font-family: var(--font-body);
}

.caption {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 12px;
}

/* ---------- stage ---------- */

.stage {
  position: relative;
  flex: 1 1 0;
  min-height: 300px;
  overflow: hidden;
  border-radius: 28px;
  border: 2px solid var(--line);
  box-shadow: var(--shadow);
  background:
    radial-gradient(90% 70% at 50% 108%, #ffe9c4 0%, transparent 62%),
    radial-gradient(70% 60% at 20% 0%, #fffbe9 0%, transparent 60%),
    linear-gradient(180deg, #bfe4ff 0%, #dff2ff 42%, #f6efdb 100%);
}

.garden-canvas {
  position: absolute;
  inset: 0;
}

.hud {
  position: absolute;
  top: 12px;
  left: 12px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  pointer-events: none;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 32px;
  padding: 0 13px;
  border-radius: 999px;
  background: rgba(255, 253, 248, 0.92);
  border: 2px solid rgba(255, 255, 255, 0.9);
  box-shadow: 0 3px 10px -4px rgba(70, 60, 40, 0.35);
  font-size: 14px;
  font-weight: 500;
  color: var(--ink);
}

.pill b {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.pill i {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  display: block;
}

.pill.fruit i {
  background: #9be04a;
  box-shadow: 0 0 0 2px #e4f5cf;
}

.pill.blue i {
  background: var(--blue);
  box-shadow: 0 0 0 2px var(--blue-soft);
}

.pill.red i {
  background: var(--red);
  box-shadow: 0 0 0 2px var(--red-soft);
}

.pill.time {
  color: var(--muted);
}

.pill.time b {
  color: var(--ink);
}

.stage-tools {
  position: absolute;
  top: 12px;
  right: 12px;
  display: flex;
  gap: 8px;
}

.chip-btn {
  height: 30px;
  padding: 0 12px;
  border-radius: 999px;
  border: 2px solid rgba(255, 255, 255, 0.9);
  background: rgba(255, 253, 248, 0.85);
  font-size: 13px;
  box-shadow: 0 3px 10px -4px rgba(70, 60, 40, 0.35);
}

.chip-btn.on {
  background: var(--violet);
  border-color: #7a4be6;
  color: #fff;
}

.stage-hint {
  position: absolute;
  bottom: 10px;
  left: 50%;
  transform: translateX(-50%);
  padding: 4px 12px;
  border-radius: 999px;
  background: rgba(255, 253, 248, 0.7);
  color: var(--muted);
  font-size: 12px;
  white-space: nowrap;
  pointer-events: none;
}

.big-play {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  display: inline-flex;
  align-items: center;
  gap: 10px;
  height: 58px;
  padding: 0 28px;
  font-size: 22px;
  font-weight: 600;
  color: #fff;
  background: var(--green);
  border: 3px solid #fff;
  border-radius: 999px;
  box-shadow:
    0 5px 0 #2f7d32,
    0 14px 30px -8px rgba(40, 90, 40, 0.5);
  animation: pulse 1.6s ease-in-out infinite;
}

@keyframes pulse {
  50% {
    transform: translate(-50%, -50%) scale(1.06);
  }
}

/* ---------- controls ---------- */

.controls .presets {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.preset {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 42px;
  padding: 6px 10px;
  text-align: left;
  font-size: 13.5px;
  font-weight: 500;
  line-height: 1.1;
  border: 2px solid var(--line);
  border-radius: 16px;
  background: var(--card-2);
  transition:
    transform 0.12s,
    background 0.15s,
    border-color 0.15s;
}

.preset:hover {
  transform: translateY(-1px);
  background: #fff;
}

.preset.active {
  border-color: var(--green);
  background: var(--green-soft);
  box-shadow: 0 0 0 3px rgba(76, 174, 79, 0.18);
}

.preset-emoji {
  font-size: 20px;
}

.preset-blurb {
  margin: 8px 2px 12px;
  color: var(--muted);
  font-size: 12.5px;
  min-height: 18px;
}

.group {
  margin-top: 10px;
  border: 2px solid var(--line);
  border-radius: 18px;
  background: var(--card-2);
  overflow: hidden;
}

.group.tone-blue {
  --tone: var(--blue);
  --tone-soft: var(--blue-soft);
}
.group.tone-red {
  --tone: var(--red);
  --tone-soft: var(--red-soft);
}
.group.tone-green {
  --tone: var(--green);
  --tone-soft: var(--green-soft);
}
.group.tone-violet {
  --tone: var(--violet);
  --tone-soft: var(--violet-soft);
}
.group.tone-sand {
  --tone: var(--sand);
  --tone-soft: var(--sand-soft);
}

.group-head {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  padding: 9px 12px;
  border: 0;
  background: var(--tone-soft);
  font-size: 15px;
  font-weight: 600;
  text-align: left;
}

.group-emoji {
  font-size: 18px;
}

.group-title {
  margin-right: auto;
}

.badge {
  padding: 2px 8px;
  font-size: 11px;
  font-weight: 500;
  color: #8a5a12;
  background: #fff;
  border-radius: 999px;
  border: 1.5px solid var(--sand);
}

.chev {
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #fff;
  color: var(--tone);
  font-size: 16px;
  line-height: 1;
}

.group-body {
  padding: 8px 12px 12px;
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.slider {
  --tone: var(--green);
}
.slider.tone-blue {
  --tone: var(--blue);
}
.slider.tone-red {
  --tone: var(--red);
}
.slider.tone-violet {
  --tone: var(--violet);
}
.slider.tone-sand {
  --tone: var(--sand);
}

.slider-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
  font-size: 13px;
}

.slider-head label {
  font-weight: 700;
  color: #4a4663;
}

.slider-head output {
  font-family: var(--font-display);
  font-size: 13px;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  background: #fff;
  border-radius: 999px;
  padding: 0 8px;
  border: 1.5px solid var(--line);
}

.slider.dirty output {
  border-color: var(--sand);
  background: var(--sand-soft);
}

input[type='range'] {
  --pct: 50%;
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 22px;
  margin: 0;
  background: transparent;
  cursor: pointer;
  --tone: var(--green);
}

.slider input[type='range'] {
  --tone: inherit;
}

input[type='range']::-webkit-slider-runnable-track {
  height: 10px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--tone, var(--green)) var(--pct), #e9dfc9 var(--pct));
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.12);
}

input[type='range']::-moz-range-track {
  height: 10px;
  border-radius: 999px;
  background: #e9dfc9;
}

input[type='range']::-moz-range-progress {
  height: 10px;
  border-radius: 999px;
  background: var(--tone, var(--green));
}

input[type='range']::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 22px;
  height: 22px;
  margin-top: -6px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid var(--tone, var(--green));
  box-shadow: 0 2px 5px rgba(60, 50, 30, 0.3);
  transition: transform 0.1s;
}

input[type='range']::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid var(--tone, var(--green));
  box-shadow: 0 2px 5px rgba(60, 50, 30, 0.3);
}

input[type='range']:hover::-webkit-slider-thumb {
  transform: scale(1.12);
}

.seed-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.seed-row label {
  font-weight: 700;
  color: #4a4663;
  font-size: 13px;
  margin-right: auto;
}

.seed-row input {
  width: 92px;
  height: 32px;
  padding: 0 10px;
  font: 600 14px var(--font-display);
  border: 2px solid var(--line);
  border-radius: 12px;
  background: #fff;
  color: var(--ink);
}

.seed-row.dirty input {
  border-color: var(--sand);
  background: var(--sand-soft);
}

.mini {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  padding: 0;
  border-radius: 50%;
  border: 2px solid var(--line);
  background: #fff;
  font-size: 14px;
}

.mini:hover {
  background: var(--card-2);
}

.restart {
